28: /**
29:  * Standard HTTP request helper returning Promise
30:  */
31: function request(options, requestBody = null) {
32:   return new Promise((resolve, reject) => {
33:     const req = http.request(options, (res) => {
34:       const chunks = [];
35:       res.on('data', (chunk) => chunks.push(chunk));
36:       res.on('end', () => {
37:         const rawBuffer = Buffer.concat(chunks);
38:         let text = null;
39:         let json = null;
40:         try {
41:           text = rawBuffer.toString('utf8');
42:           json = JSON.parse(text);
43:         } catch (_) {}
44:         resolve({
45:           statusCode: res.statusCode,
46:           headers: res.headers,
47:           buffer: rawBuffer,
48:           text,
49:           json,
50:         });
51:       });
52:     });
53: 
54:     req.on('error', reject);
55:     req.setTimeout(15000, () => {
56:       req.destroy(new Error('Request timed out (15s)'));
57:     });
58: 
59:     if (requestBody) {
60:       req.write(requestBody);
61:     }
62:     req.end();
63:   });
64: }
