69: async function waitForServer(port, maxWaitMs = 6000) {
70:   const start = Date.now();
71:   const statusFile = path.join(__dirname, '.server-port');
72:   while (Date.now() - start < maxWaitMs) {
73:     let checkPort = port;
74:     if (fs.existsSync(statusFile)) {
75:       try {
76:         const p = parseInt(fs.readFileSync(statusFile, 'utf8').trim(), 10);
77:         if (p) checkPort = p;
78:       } catch (_) {}
79:     }
80:     try {
81:       const res = await request({
82:         hostname: TEST_HOST,
83:         port: checkPort,
84:         path: '/health',
85:         method: 'GET',
86:       });
87:       if (res.statusCode === 200 && res.json && res.json.status === 'ok') {
88:         activePort = checkPort;
89:         return true;
90:       }
91:     } catch (_) {}
92:     await new Promise((r) => setTimeout(r, 100));
93:   }
94:   return false;
95: }
