### 3.2 Mock Hls.js Simulation Engine (`window.Hls`)
The test environment simulates the full HLS.js streaming lifecycle and event bus without external dependencies.

#### Properties & Configuration:
- `config`: Verified against webOS 1.5GB RAM limits (`maxBufferSize: 30 * 1024 * 1024`, `maxBufferLength: 30`, `liveSyncDurationCount: 3`).
- `levels`: Array of quality ladders (`360p`, `720p`, `1080p`, `4K`).
- `currentLevel`: Getter/setter for quality switching.
- `subtitleTracks`: Array of subtitle track objects.
- `subtitleTrack`: Getter/setter for active subtitle index (-1 for disabled).
- `destroyed`: Boolean flag tracking resource cleanup.

#### Event Constants & Enums:
- `Hls.isSupported()` returns `true`.
- `Hls.Events`: `MANIFEST_LOADING`, `MANIFEST_LOADED`, `MANIFEST_PARSED`, `LEVEL_LOADED`, `FRAG_LOADING`, `FRAG_LOADED`, `ERROR`, `MEDIA_ATTACHED`, `MEDIA_DETACHED`, `SUBTITLE_TRACKS_UPDATED`, `SUBTITLE_TRACK_SWITCH`.
- `Hls.ErrorTypes`: `NETWORK_ERROR`, `MEDIA_ERROR`, `KEY_SYSTEM_ERROR`, `MUX_ERROR`, `OTHER_ERROR`.
- `Hls.ErrorDetails`: `MANIFEST_LOAD_ERROR`, `MANIFEST_LOAD_TIMEOUT`, `BUFFER_STALLED_ERROR`, `FRAG_LOAD_ERROR`, `LEVEL_LOAD_ERROR`, `INTERNAL_EXCEPTION`.

```javascript
function installHlsMock(window) {
  function MockHls(config) {
    this.config = config || {};
    this.media = null;
    this.url = null;
    this.destroyed = false;
    this._listeners = {};

    this.levels = [
      { bitrate: 800000, width: 640, height: 360, name: '360p' },
      { bitrate: 2500000, width: 1280, height: 720, name: '720p' },
      { bitrate: 5000000, width: 1920, height: 1080, name: '1080p' },
      { bitrate: 15000000, width: 3840, height: 2160, name: '4K' }
    ];
    this._currentLevel = -1;

    this.subtitleTracks = [
      { id: 0, lang: 'en', name: 'English' },
      { id: 1, lang: 'es', name: 'Spanish' }
    ];
    this._subtitleTrack = -1;
  }

  Object.defineProperty(MockHls.prototype, 'currentLevel', {
    get: function () { return this._currentLevel; },
    set: function (lvl) {
      this._currentLevel = lvl;
      this.trigger(MockHls.Events.LEVEL_LOADED, { level: lvl });
    }
  });

  Object.defineProperty(MockHls.prototype, 'subtitleTrack', {
    get: function () { return this._subtitleTrack; },
    set: function (trackId) {
      this._subtitleTrack = trackId;
      this.trigger(MockHls.Events.SUBTITLE_TRACK_SWITCH, { id: trackId });
    }
  });

  MockHls.prototype.on = function (event, cb) {
    if (!this._listeners[event]) this._listeners[event] = [];
    this._listeners[event].push(cb);
  };

  MockHls.prototype.off = function (event, cb) {
    if (!this._listeners[event]) return;
    this._listeners[event] = this._listeners[event].filter(function (fn) { return fn !== cb; });
  };

  MockHls.prototype.trigger = function (event, data) {
    const list = this._listeners[event] || [];
    for (let i = 0; i < list.length; i++) {
      try { list[i](event, data || {}); } catch (err) { console.error('HLS trigger error:', err); }
    }
  };

  MockHls.prototype.attachMedia = function (mediaElement) {
    this.media = mediaElement;
    this.trigger(MockHls.Events.MEDIA_ATTACHED, { media: mediaElement });
  };

  MockHls.prototype.loadSource = function (url) {
    this.url = url;
    this.trigger(MockHls.Events.MANIFEST_LOADING, { url });
    const self = this;
    setTimeout(function () {
      if (!self.destroyed) {
        self.trigger(MockHls.Events.MANIFEST_LOADED, { url, levels: self.levels });
        self.trigger(MockHls.Events.MANIFEST_PARSED, { levels: self.levels });
      }
    }, 10);
  };

  MockHls.prototype.startLoad = function (startPosition) {
    this.startPosition = startPosition;
    this.loading = true;
  };

  MockHls.prototype.stopLoad = function () {
    this.loading = false;
  };

  MockHls.prototype.recoverMediaError = function () {
    this._recoveredMediaErrors = (this._recoveredMediaErrors || 0) + 1;
  };

  MockHls.prototype.destroy = function () {
    this.destroyed = true;
    this.media = null;
    this.url = null;
    this._listeners = {};
    if (this._onDestroy) this._onDestroy();
  };

  MockHls.isSupported = function () { return true; };

  MockHls.Events = {
    MANIFEST_LOADING: 'hlsManifestLoading',
    MANIFEST_LOADED: 'hlsManifestLoaded',
    MANIFEST_PARSED: 'hlsManifestParsed',
    LEVEL_LOADED: 'hlsLevelLoaded',
    FRAG_LOADING: 'hlsFragLoading',
    FRAG_LOADED: 'hlsFragLoaded',
    ERROR: 'hlsError',
    MEDIA_ATTACHED: 'hlsMediaAttached',
    MEDIA_DETACHED: 'hlsMediaDetached',
    SUBTITLE_TRACKS_UPDATED: 'hlsSubtitleTracksUpdated',
    SUBTITLE_TRACK_SWITCH: 'hlsSubtitleTrackSwitch'
  };

  MockHls.ErrorTypes = {
    NETWORK_ERROR: 'networkError',
    MEDIA_ERROR: 'mediaError',
    KEY_SYSTEM_ERROR: 'keySystemError',
    MUX_ERROR: 'muxError',
    OTHER_ERROR: 'otherError'
  };

  MockHls.ErrorDetails = {
    MANIFEST_LOAD_ERROR: 'manifestLoadError',
    MANIFEST_LOAD_TIMEOUT: 'manifestLoadTimeOut',
    BUFFER_STALLED_ERROR: 'bufferStalledError',
    FRAG_LOAD_ERROR: 'fragLoadError',
    LEVEL_LOAD_ERROR: 'levelLoadError',
    INTERNAL_EXCEPTION: 'internalException'
  };

  window.Hls = MockHls;
}
