const MOCK_M5_ROUTES = {
  // 1. Health Probe
  '/health': { status: 'ok', uptime: 100, version: '1.0.0' },

  // 2. Server Cluster Nodes
  '/api/servers': {
    servers: [
      { name: 'secret', '4k': true },
      { name: 'Nebula', '4k': false },
      { name: 'Lisbon', '4k': false },
      { name: 'Solara', '4k': false },
      { name: 'Athens', '4k': false }
    ]
  },

  // 3. Movie Stream Resolution (Dune: Part Two TMDB 693134 or Inception 27205)
  '/api/stream': function (url) {
    if (url.includes('tmdbId=999999')) {
      return { _errorStatus: 404, _errorText: 'Stream not found' };
    }
    if (!url.includes('tmdbId=')) {
      return { _errorStatus: 400, _errorText: 'Missing tmdbId' };
    }

    const isTV = url.includes('type=tv');
    const isNebula = url.includes('server=Nebula');
    const serverName = isNebula ? 'Nebula' : 'secret';

    const baseProxy = 'http://127.0.0.1:8088/hls/proxy?url=';
    const originalUrl = isTV
      ? 'https://lightspeed.st/hls/series_master.m3u8'
      : (isNebula ? 'https://lightspeed.st/hls/nebula_master.m3u8' : 'https://lightspeed.st/hls/master.m3u8');

    return {
      success: true,
      streamUrl: baseProxy + encodeURIComponent(originalUrl),
      originalUrl: originalUrl,
      server: serverName,
      subtitles: [
        { label: 'English', srclang: 'en', src: 'http://127.0.0.1:8088/proxy/sub?url=en.srt' },
        { label: 'Spanish', srclang: 'es', src: 'http://127.0.0.1:8088/proxy/sub?url=es.srt' }
      ]
    };
  },

  // 4. Subtitle Proxy (.srt to WebVTT)
  '/proxy/sub': function () {
    return 'WEBVTT\n\n1\n00:00:01.000 --> 00:00:04.000\nHello from Cinejoy TV Subtitles\n';
  }
};
