## 5. Test Harness Factory Blueprint (`createM5Harness`)

The test suite constructs isolated, repeatable DOM and application instances via `createM5Harness`:

```javascript
function createM5Harness(options) {
  const opts = options || {};
  const customRoutes = opts.mockRoutes || {};

  const htmlPath = path.resolve(__dirname, 'index.html');
  const configPath = path.resolve(__dirname, 'js/config.js');
  const navPath = path.resolve(__dirname, 'js/navigation.js');
  const tmdbPath = path.resolve(__dirname, 'js/tmdb.js');
  const homePath = path.resolve(__dirname, 'js/views/home.js');
  const catalogPath = path.resolve(__dirname, 'js/views/catalog.js');
  const searchPath = path.resolve(__dirname, 'js/views/search.js');
  const detailsPath = path.resolve(__dirname, 'js/views/details.js');
  const playerPath = path.resolve(__dirname, 'js/player.js');
  const appPath = path.resolve(__dirname, 'js/app.js');

  const html = fs.readFileSync(htmlPath, 'utf8');
  const dom = new JSDOM(html, {
    url: 'http://localhost/#home',
    runScripts: 'outside-only'
  });
  const window = dom.window;

  window.__TEST_M5__ = true;
  installScrollMocks(window);
  installLayoutMock(window);
  installVideoMock(window);
  installHlsMock(window);
  installMockFetch(window, customRoutes);

  // Load application scripts in sequence
  window.eval(fs.readFileSync(configPath, 'utf8'));
  window.eval(fs.readFileSync(navPath, 'utf8'));
  window.eval(fs.readFileSync(tmdbPath, 'utf8'));
  window.eval(fs.readFileSync(homePath, 'utf8'));
  window.eval(fs.readFileSync(catalogPath, 'utf8'));
  window.eval(fs.readFileSync(searchPath, 'utf8'));
  window.eval(fs.readFileSync(detailsPath, 'utf8'));
  if (fs.existsSync(playerPath)) {
    window.eval(fs.readFileSync(playerPath, 'utf8'));
  }
  window.eval(fs.readFileSync(appPath, 'utf8'));

  if (window.CinejoyApp && typeof window.CinejoyApp.init === 'function') {
    window.CinejoyApp.init();
  }

  return {
    dom: dom,
    window: window,
    app: window.CinejoyApp,
    nav: window.SpatialNav,
    player: window.PlayerController,
    osd: window.PlayerOSDController,
    video: window.document.getElementById('main-video-player')
  };
}
```

